var e=JSON.parse(`[{"id":"avrupa-hun","name":"Avrupa Hunları","short":"İdil'i aşıp IV-V. yüzyılda Orta Avrupa'da kurulan bozkır birliği","aliases":["Batı Hunları","Hun İmparatorluğu"],"region":"bati","start":375,"end":469,"startNote":"İdil'i aşma TDV'de 374-375; Britannica güneydoğu Avrupa'ya girişi yaklaşık 370 diye yazar.","endNote":"TDV İdil maddesi Batı Hun aralığını 374-469 verir. Britannica 455 Nedao'dan sonra siyasî rollerinin bittiğini, Dengizik'in 468'de öldüğünü TDV kaydeder.","capital":"Sabit şehir adı kayıtlarda yok; merkez 400 civarında Orta Avrupa'ya kaydı","religion":"Açılan sayfalarda resmî bir din adı yok","confidence":"tartismali","confidenceNote":"TDV bu birliği Asya Hunlarının batıdaki devamı ve Türk sayar. Britannica Avrupa Hunları ile Çin kayıtlarındaki Hiung-nu ilişkisini belirsiz bırakır; Eftalitler de bazen Hun diye anılır ama bağları ayrı bir sorudur.","summary":"IV. yüzyılın sonlarında İdil ötesinden gelen atlı birlik önce Alanları, ardından Ostrogotları sürdükten sonra Tuna sınırına dayandı. V. yüzyılda Rua, sonra Attila ve Bleda döneminde Doğu Roma vergiye bağlandı. Attila'nın 453'teki ölümünden sonra oğullar arasındaki çekişme ve bağlı Germen grupların isyanı birliği dağıttı.","legacy":"Kavimler göçünü hızlandırdı. Dil ve soy bağı az ve tartışmalı izlere dayanır; Avrupa'da ayrı bir Hun halkı olarak VI. yüzyıla kalmadılar.","essay":["IV. yüzyılın sonunda İdil ötesinden batıya yönelen atlı birlik, Alan ve Ostrogot direncini kırarak Tuna sınırına dayandı. V. yüzyılda Rua, ardından Bleda ile Attila döneminde Doğu Roma vergiye bağlandı ve Orta Avrupa'da bir bozkır gücü kuruldu.","Attila'nın 453'teki ölümünden sonra oğullar arasındaki taht çekişmesi ve bağlı Germen grupların isyanı birliği dağıttı; Avrupa'da ayrı bir Hun halkı olarak VI. yüzyıla kalmadılar. TDV bu birliği Asya Hunlarının batı kolu ve Türk sayar; Britannica, Çin kayıtlarındaki Hiung-nu ile bağı belirsiz bırakır. Dil ve soy bağı bakımından geriye az ve tartışmalı izler kalır."],"sources":[{"title":"TDV İslâm Ansiklopedisi, TÜRK","url":"https://islamansiklopedisi.org.tr/turk"},{"title":"TDV İslâm Ansiklopedisi, İDİL BULGAR HANLIĞI","url":"https://islamansiklopedisi.org.tr/idil-bulgar-hanligi"},{"title":"Britannica, Hun","url":"https://www.britannica.com/topic/Hun-people"}],"rulers":[{"id":"avrupa-hun-balamir","name":"Balamir","title":"başbuğ","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"kayıtlarda yok","reign":[374,null],"reignNote":"TDV onu 370'lerde İdil boyunun başı diye yazar. Ammianus'a dayanan Britannica, IV. yüzyılda Hunların tek kralı olup olmadığını tartışmalı sayar.","summary":"TDV'ye göre 374-375'te İdil'i aşıp Alanları ve Ostrogotları batıya süren önderdir. Adı çağdaş Roma tasvirinde geçmez.","traits":[],"contribution":"TDV anlatısında Avrupa'ya geçiş onun adıyla başlar.","harm":"","wives":[],"children":[],"wars":[{"name":"Alan ve Ostrogot seferi","when":"374-375","foe":"Alanlar, Ostrogotlar","result":"zafer","note":"TDV; tek komutan olarak Balamir tartışmalıdır."}],"legends":["Balamir'in bütün Hunların kralı olduğu sonraki anlatılardan gelir; IV. yüzyılda tek hükümdar olup olmadığı kayıtlarda çözülmüş değildir."],"sources":[{"title":"TDV İslâm Ansiklopedisi, TÜRK","url":"https://islamansiklopedisi.org.tr/turk"},{"title":"Britannica, Hun","url":"https://www.britannica.com/topic/Hun-people"}]},{"id":"avrupa-hun-rua","name":"Rua","title":"kral","birth":null,"birthNote":"kayıtlarda yok","death":434,"deathNote":"TDV ölümü 433, Britannica 434 diye yazar.","reign":[432,434],"reignNote":"Britannica'ya göre 432'de dağınık Hun grupları tek kral altında toplandı. Rugila diye de anılır.","summary":"Orta Tuna ve Tisa havzasını tutan, çeşitli Germen ve Slav gruplarını bağlayan hükümdar. Ölünce yerini kardeşi Muncuk'un oğulları Attila ve Bleda aldı.","traits":[],"contribution":"Hun liderliğini tek elde topladığı kaydedilir.","harm":"","wives":[],"children":[],"wars":[],"legends":[],"sources":[{"title":"TDV İslâm Ansiklopedisi, TÜRK","url":"https://islamansiklopedisi.org.tr/turk"},{"title":"Britannica, Hun","url":"https://www.britannica.com/topic/Hun-people"}]},{"id":"avrupa-hun-bleda","name":"Bleda","title":"kral","birth":null,"birthNote":"kayıtlarda yok","death":445,"deathNote":"TDV yalnızca öldüğünü yazar. Britannica Attila'nın kardeşini öldürdüğünü söyler.","reign":[434,445],"reignNote":"Attila ile ortak saltanat. Britannica Bleda'yı ağabey diye anar.","summary":"Rua'nın yeğeni. Yaklaşık on bir yıl Attila ile birlikte hüküm sürdü. 445'te öldü; ölüm şekli kaynaklarda ayrılır.","traits":[],"contribution":"","harm":"","wives":[],"children":[],"wars":[{"name":"Margus antlaşması","when":"434","foe":"Doğu Roma","result":"antlasma","note":"Ortak hükümdarlıkta yapıldı. Roma, Hunlara ödediği desteği iki katına çıkarmayı kabul etti."}],"legends":[],"sources":[{"title":"TDV İslâm Ansiklopedisi, TÜRK","url":"https://islamansiklopedisi.org.tr/turk"},{"title":"Britannica, Hun","url":"https://www.britannica.com/topic/Hun-people"}]},{"id":"avrupa-hun-attila","name":"Attila","title":"kral","birth":null,"birthNote":"kayıtlarda yok","death":453,"deathNote":"TDV ve Britannica aynı yılı verir; ölüm biçimi açılan sayfalarda anlatılmaz.","reign":[434,453],"reignNote":"434-445 Bleda ile ortak, 445'ten sonra tek başına. Babası TDV'ye göre Muncuk'tur.","summary":"Doğu Roma'dan yıllık vergi alan, Balkanlar'ı ve sonra Galya ile Kuzey İtalya'yı zorlayan hükümdar. TDV, doğuda Aral'dan batıda Ren'e kadar çok sayıda topluluğun bağlandığını yazar. 453'te ölünce birlik dağılmaya başladı.","traits":[],"contribution":"Doğu Roma'yı ağır bir vergiye bağladı.","harm":"447 Balkan seferinde kentler tahrip edildi. 451'de Galya yağmalandı.","wives":[],"children":[{"name":"İlek","mother":"","note":"TDV'ye göre Attila'nın yerine geçen oğul","certainty":"olasi"},{"name":"Dengizik","mother":"","note":"TDV'ye göre oğul","certainty":"olasi"},{"name":"İrnek","mother":"","note":"TDV'ye göre küçük oğul; İdil maddesinde İrne diye de geçer","certainty":"olasi"}],"wars":[{"name":"Tuna sınırı seferi","when":"441","foe":"Doğu Roma","result":"zafer","note":"Margus'ta kararlaştırılan ödeme gelmeyince açıldı. Ordu Konstantinopolis yakınına indi."},{"name":"Balkan seferi","when":"447","foe":"Doğu Roma imparatoru II. Theodosios","result":"zafer","note":"TDV: 6000 libre altın tazminat ve 2100 libre yıllık vergiyle barış. Sofya, Filibe, Preslav, Lüleburgaz ve Büyükçekmece hattı anılır."},{"name":"Theodosios barışı","when":"447","foe":"Doğu Roma","result":"antlasma","note":"Aynı seferin sonu."},{"name":"Campus Mauriacus (Katalaun ovaları)","when":"451","foe":"Batı Roma kumandanı Aetius ve Vizigotlar","result":"belirsiz","note":"TDV iki tarafın da çekildiğini, Britannica Attila'nın yenildiğini yazar. Bu onun kayıtlardaki tek bozgunu sayılır."},{"name":"İtalya seferi","when":"452","foe":"Batı Roma","result":"belirsiz","note":"Kuzey İtalya yağmalandı. TDV dönüşü Papa Leon'un ricasına bağlar; Britannica kıtlık ve salgını öne çıkarır."}],"legends":["TDV, Honoria'nın nişan yüzüğünün Batı Roma üzerinde hak iddiasına bahane edildiğini yazar.","Papa Leon'un yalvarıp Attila'yı İtalya'dan çevirdiği anlatı TDV'de vardır; Britannica çekilmeyi kıtlık ve salgınla açıklar."],"sources":[{"title":"TDV İslâm Ansiklopedisi, TÜRK","url":"https://islamansiklopedisi.org.tr/turk"},{"title":"Britannica, Hun","url":"https://www.britannica.com/topic/Hun-people"}]},{"id":"avrupa-hun-ilek","name":"İlek","title":"kral","birth":null,"birthNote":"kayıtlarda yok","death":455,"deathNote":"TDV, Gepid kralıyla savaşta öldüğünü yazar, yıl vermez. Britannica Hunların 455'te Nedao'da bozulduğunu söyler, komutan adı vermez. Yıl bu iki kaydın yan yana konmasıdır.","reign":[453,455],"reignNote":"Attila'nın yerine geçti. Kardeşleriyle taht kavgası TDV'de dağılmanın sebebi sayılır.","summary":"Attila'nın oğlu. Kısa saltanatı Germen isyanları ve kardeş çekişmesi içinde kapandı.","traits":[],"contribution":"","harm":"","wives":[],"children":[],"wars":[{"name":"Nedao","when":"455","foe":"Gepidler, Ostrogotlar, Heruller","result":"yenilgi","note":"Irmak adı Britannica'da geçer ve yeri belirsizdir. TDV yalnızca Gepid kralıyla savaşı anar."}],"legends":[],"sources":[{"title":"TDV İslâm Ansiklopedisi, TÜRK","url":"https://islamansiklopedisi.org.tr/turk"},{"title":"Britannica, Hun","url":"https://www.britannica.com/topic/Hun-people"}]},{"id":"avrupa-hun-dengizik","name":"Dengizik","title":"kral","birth":null,"birthNote":"kayıtlarda yok","death":468,"deathNote":"TDV: Bizans'a yenildi, esir düştü, İstanbul'da idam edildi.","reign":[null,468],"reignNote":"Başlangıç yılı kayıtlarda yok.","summary":"Attila'nın oğlu. Birliğin dağılmasından sonra Bizans sınırında tutunamadı.","traits":[],"contribution":"","harm":"","wives":[],"children":[],"wars":[{"name":"Bizans seferi","when":"468","foe":"Bizans","result":"yenilgi","note":"Esir edilip idam edildi."}],"legends":[],"sources":[{"title":"TDV İslâm Ansiklopedisi, TÜRK","url":"https://islamansiklopedisi.org.tr/turk"}]},{"id":"avrupa-hun-irnek","name":"İrnek","title":"başbuğ","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"kayıtlarda yok","reign":[null,null],"reignNote":"Yıl yok. TDV İdil maddesinde İrne diye anılır.","summary":"Attila'nın küçük oğlu. TDV, kendine bağlı gruplarla Karadeniz kuzeyine döndüğünü ve oradaki Ogurlarla karışıp Bulgar adının bu karışımdan çıktığını yazar. Bu soy bağı bir yorumdur.","traits":[],"contribution":"","harm":"","wives":[],"children":[],"wars":[],"legends":["İrnek'in Bulgarların atası sayılması TDV'nin etnogenez anlatısıdır; kişi olarak ayrıca belgelenmiş bir saltanatı yoktur."],"sources":[{"title":"TDV İslâm Ansiklopedisi, TÜRK","url":"https://islamansiklopedisi.org.tr/turk"},{"title":"TDV İslâm Ansiklopedisi, İDİL BULGAR HANLIĞI","url":"https://islamansiklopedisi.org.tr/idil-bulgar-hanligi"}]}]},{"id":"avar-kaganligi","name":"Avar Kağanlığı","short":"Karpat havzasında 567'den VIII. yüzyıl sonuna kadar süren kağanlık","aliases":["Avar Hakanlığı","Panonya Avarları"],"region":"bati","start":567,"end":805,"startNote":"557-558'de Azak ve Bizans sınırı, 567'de Gepidlerin yenilmesi, 568'de Longobardların İtalya'ya çekilmesiyle havza Avarlarda kaldı.","endNote":"Frank seferleri 791, 795 ve 796. TDV ve Britannica siyasî teslimiyeti 805'e koyar. Vikipedi Frank sarayında Avar elçisini 822'ye kadar anar.","capital":"Tuna ile Tisa arası; şehir adı kayıtlarda yok","religion":"Bozkır inancı; dağılmayla birlikte Hıristiyanlaşma","confidence":"tartismali","confidenceNote":"Köken tartışmalıdır. TDV, Juan-juanlarla ilgisi olmadığını ve Uar-Hun kolu olduklarını yazar. Britannica Moğolistan çıkışını muhtemel sayar. Göktürkler onları Varchonit ve kaçak kul diye anmaktaydı. Yeni arkeogenetik çalışmalar elit çekirdekte İç Asya ve Rouran ihtimalini güçlendirir; bütün nüfusun Rouran olduğu kanıtlanmış değildir. TDV'nin AVARLAR maddesindeki Dağıstan Avarları ayrı bir halktır.","summary":"Göktürk genişlemesi önünden batıya gelen ve Bizans'ın Avar dediği birlik, 567'de Longobardlarla Gepidleri yenip Karpat havzasını tuttu. Bayan döneminde Tuna-Tisa merkez oldu. 626 İstanbul kuşatması başarısız kalınca nüfuz kırıldı. VIII. yüzyıl sonunda Frank seferleri kağanlığı parçaladı.","legacy":"Slav gruplarının Balkanlar'a inmesinde payları oldu. Kağan unvanı Avrupa kaynaklarına bu yolla geçti. Siyasî yapı 805'ten sonra eridi.","essay":["Göktürk genişlemesi önünden batıya gelen ve Bizans kaynaklarının Avar dediği birlik, 567'de Longobardlarla birlikte Gepidleri yenerek Karpat havzasını tuttu. Bayan döneminde Tuna-Tisa hattı merkez oldu; 626'daki İstanbul kuşatması başarısız kalınca nüfuz kırıldı.","VIII. yüzyılın sonunda Frank seferleri (791-796) kağanlığı parçaladı; siyasî teslimiyet 805'e konur. Köken tartışmalıdır: TDV onları Uar-Hun kolu sayıp Juan-juan bağını reddeder, Britannica Moğolistan çıkışını muhtemel görür. Yeni arkeogenetik çalışmalar İç Asya ve Rouran ihtimalini güçlendirse de bütün nüfusun Rouran olduğu kanıtlanmış değildir.","Slav gruplarının Balkanlar'a inmesinde pay sahibi oldular; kağan unvanı Avrupa kaynaklarına bu yolla geçti."],"sources":[{"title":"TDV İslâm Ansiklopedisi, TÜRK","url":"https://islamansiklopedisi.org.tr/turk"},{"title":"TDV İslâm Ansiklopedisi, MACARİSTAN","url":"https://islamansiklopedisi.org.tr/macaristan"},{"title":"Britannica, Avar","url":"https://www.britannica.com/topic/Avar"},{"title":"TDV İslâm Ansiklopedisi, AVARLAR","url":"https://islamansiklopedisi.org.tr/avarlar"}],"rulers":[{"id":"avar-bayan","name":"Bayan","title":"kağan","birth":null,"birthNote":"kayıtlarda yok","death":602,"deathNote":"Vikipedi 602 der; maddenin savaş bölümü kaynak göstermez. TDV ölüm yılı vermez.","reign":[562,602],"reignNote":"Vikipedi ilk kağanlığı 562-602 diye yazar ve atıfı zayıftır. TDV yalnızca en güçlü dönemin Bayan zamanı olduğunu söyler. 626 kuşatması ona bağlanamaz.","summary":"Avarların en güçlü kağanı diye anılır. Merkezi Tuna-Tisa arasına aldı. TDV sınırları Dinyeper'den Elbe'ye, Adriyatik'ten Kuzey Denizi kıyılarına kadar genişlettiğini yazar; bu uçlar abartılı olabilir.","traits":[],"contribution":"Kağanlığın Karpat havzasındaki çekirdeğini kurdu.","harm":"Bizans sınır kentlerine ve Frank topraklarına akınlar açtı.","wives":[],"children":[],"wars":[{"name":"Gepid savaşı","when":"567","foe":"Gepid kralı Cunimund","result":"zafer","note":"Longobardlarla birlikte. TDV Macaristan 567 Longobard-Avar ittifakını yazar."},{"name":"Sigebert seferleri","when":"562 ve 566","foe":"Frank kralı I. Sigebert","result":"belirsiz","note":"Vikipedi 562'de yenilgi, 566'da galibiyet der. TDV Frankları yendiklerini kaydeder, yıl vermez."}],"legends":["Vikipedi, Bayan'ın Cunimund'un kafatasından kadeh yaptırıp Alboin'e verdiğini yazar. Anlatı Longobard geleneğindendir; TDV'de yoktur."],"sources":[{"title":"TDV İslâm Ansiklopedisi, TÜRK","url":"https://islamansiklopedisi.org.tr/turk"},{"title":"Wikipedia, Bayan I","url":"https://en.wikipedia.org/wiki/Bayan_I"}]},{"id":"avar-kagan-adi-yok","name":"kayıtlarda adı geçmiyor","title":"kağan","birth":null,"birthNote":"kayıtlarda adı geçmiyor","death":null,"deathNote":"kayıtlarda adı geçmiyor","reign":[null,805],"reignNote":"626 ve Frank savaşlarının kağan adı açılan sayfalarda yok. 630'da kağanın zamansız öldüğü TDV'de geçer, adı verilmez.","summary":"Bayan'dan sonraki kağanların kişisel adları bu turda açılan sayfalarda güvenilir biçimde yok. 626 başarısızlığı ve 630 Bulgar isyanı nüfuzu düşürdü. Frank seferleri 805'te siyasî varlığı kapattı.","traits":[],"contribution":"","harm":"","wives":[],"children":[],"wars":[{"name":"İstanbul kuşatması","when":"626","foe":"Bizans; Sâsânîler müttefik","result":"yenilgi","note":"Şehir alınamadı. TDV, Avar emrindeki Slavların isyanını ve donanma yokluğunu yazar. Britannica kuşatmanın şehre yaklaştığını söyler."},{"name":"Frank seferleri","when":"791-805","foe":"Charlemagne (Büyük Charles)","result":"yenilgi","note":"791, 795, 796 seferleri. Teslimiyet TDV ve Britannica'da 805."}],"legends":["Göktürklerin 'sahte Avar' demesi bir hakaret ve siyaset dili olarak da okunur; gerçek adın Var ve Chunni olduğu tezi Theophylaktos'a dayanır ve tartışmalıdır."],"sources":[{"title":"TDV İslâm Ansiklopedisi, TÜRK","url":"https://islamansiklopedisi.org.tr/turk"},{"title":"Britannica, Avar","url":"https://www.britannica.com/topic/Avar"},{"title":"TDV İslâm Ansiklopedisi, AVARLAR","url":"https://islamansiklopedisi.org.tr/avarlar"}]}]},{"id":"hazar-kaganligi","name":"Hazar Kağanlığı","short":"VII-X. yüzyıllarda Kuzey Kafkasya, İdil ve Karadeniz kuzeyinde ticaret devleti","aliases":["Hazar Hakanlığı","Hazarlar"],"region":"bati","start":630,"end":969,"startNote":"Batı Göktürk bağının kopması TDV'de 630. Britannica VII. yüzyıl başında bağımsızlaştıklarını yazar.","endNote":"Britannica Sviatoslav'ın 965 seferiyle gücün kırıldığını, TDV hakanın 965'te Hârizmlilere sığındığını ve Semender'in 968'den sonraki seferlerde harap olduğunu yazar. Vikipedi Atil'in yağmasını 969'a koyar. Hazar adı XI. yüzyıl içinde de anılır.","capital":"Önce Belencer, Arap baskısından sonra İdil (İtil, Atil)","religion":"Halkta Tengri inancı, İslâm ve Hıristiyanlık bir arada; yönetici zümrede Mûsevîlik","confidence":"kayit","confidenceNote":"Devletin varlığı kayıtlıdır. Mûsevîliğin yılı ayrılır: Yahuda Halevi 740, Mes'ûdî Hârûnürreşîd dönemi (786-809), Britannica yaklaşık 740. Kabulün derinliği belirsizdir. Hakan adlarının çoğu yoktur. Bulan ve Obadiah yalnızca Hasdai-Yûsuf mektubundadır. Böri Şad ve Bulu Han açılan TDV ve Britannica maddelerinde hakan diye geçmez. Ercan adlı bir muharebe de yoktur; 730 bozgunu Erdebil'dedir.","summary":"Hazarlar Sabar bakiyesi ve Batı Göktürk ucu olarak Kafkasya'da sivrildi, 630'dan sonra kendi kağanlıklarını kurdu. Belencer sonra İdil, Hazar denizi-Karadeniz ticaretinin düğümü oldu. Hükümdar kutsal hakan, icra hakan beg elindeydi. Halife ordularını Kafkasya'da durdurdular; 965-969 Rus seferleri bu gücü kırdı.","legacy":"Arap ilerleyişini Kafkasların kuzeyinde kestiler. İdil Bulgarları ve bir süre Macarlar ile Slav grupları onlara bağlı yaşadı. Yönetici din olarak Yahudilik bozkırda istisnadır. Hazarca bir metin kalmamıştır.","essay":["Sabar bakiyesi ve Batı Göktürk ucu olarak Kafkasya'nın kuzeyinde sivrilen Hazarlar, 630'dan sonra kendi kağanlıklarını kurdular. Belencer, ardından İdil, Hazar-Karadeniz ticaretinin düğümü oldu. Hükümdarlık iki başlıydı: kutsal hakan ve icra yetkisini elinde tutan hakan beg.","Halife ordularını Kafkasya'nın kuzeyinde durdurdular; 965-969 Rus seferleri bu gücü kırdı. İdil Bulgarları ve bir süre Macarlar ile Slav grupları onlara bağlı yaşadı. Yönetici din olarak Yahudilik bozkırda istisnadır ve Hazarca yazılı bir metin kalmamıştır."],"sources":[{"title":"TDV İslâm Ansiklopedisi, HAZARLAR","url":"https://islamansiklopedisi.org.tr/hazarlar"},{"title":"Britannica, Khazar","url":"https://www.britannica.com/topic/Khazar"}],"rulers":[{"id":"hazar-hakan-adi-yok","name":"kayıtlarda adı geçmiyor","title":"hakan","birth":null,"birthNote":"kayıtlarda adı geçmiyor","death":null,"deathNote":"626 civarında Herakleios'un kızını isteyen hakan düğünden önce öldü; adı yok.","reign":[630,null],"reignNote":"Arap savaşları döneminin hakanları TDV'de adsızdır. Bu kayıt tek kişi değil, adı geçmeyen makamdır.","summary":"Bağımsızlığın ilk yüzyılında hakanların özel adı verilmez. Çorpan Tarhan ve As-Tarhan kumandan olarak ayrılır. Mervân seferinde hakan kısa süre İslâm'ı kabul edip sonra döndü.","traits":[],"contribution":"Kafkas geçitlerinde halife ordularını birkaç kez durdurdular.","harm":"","wives":[],"children":[],"wars":[{"name":"Belencer","when":"652-653","foe":"Selmân b. Rebîa kumandasındaki ordu","result":"zafer","note":"Derbend aşıldı, başkent Belencer'e kadar gelindi. Hazarlar orduyu yendi. Ercan diye ayrı bir savaş açılan sayfalarda yok."},{"name":"Mercülhicâre","when":"717'den yaklaşık beş yıl sonra","foe":"Emevî ordusu","result":"zafer","note":"TDV: Kıpçak ve başka Türk boylarının yardımıyla müslüman ordusu bozuldu."},{"name":"Belencer'in düşmesi","when":"722-723","foe":"Cerrâh b. Abdullah el-Hakemî","result":"yenilgi","note":"TDV, Cerrâh'ın Tarki ve Belencer'i aldığını yazar. Yıl Vikipedi'nin 722-723 kaydına dayanır."},{"name":"Erdebil","when":"730","foe":"Cerrâh b. Abdullah","result":"zafer","note":"Cerrâh Azerbaycan'a çekilerek yenildi. Vikipedi komutanı Barjik diye anar; TDV ad vermez. Ercan bu savaşın adı değildir."},{"name":"Mervân'ın İdil seferi","when":"732 valiliğinden sonra; Vikipedi 737","foe":"Mervân b. Muhammed","result":"yenilgi","note":"Belencer alındı, ordu İdil'e vardı. Hakanın gönderdiği ordu yenildi."},{"name":"Mervân barışı","when":"aynı seferin sonu","foe":"Mervân b. Muhammed","result":"antlasma","note":"İslâm'ı kabul şartıyla barış. İdil'de iki fakih bırakıldı. Hakan kısa süre sonra eski dinine döndü."}],"legends":["Bulu Han ve Böri Şad bağlantısı açılan TDV ve Britannica maddelerinde kurulmaz.","Hakanın saltanat süresini boğularak seçtiği ve süre dolunca öldürüldüğü anlatı İbn Fadlân çizgisindedir; her hakan için doğrulanmış bir olay değildir."],"sources":[{"title":"TDV İslâm Ansiklopedisi, HAZARLAR","url":"https://islamansiklopedisi.org.tr/hazarlar"}]},{"id":"hazar-corpan-tarhan","name":"Çorpan Tarhan","title":"tarhan","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"kayıtlarda yok","reign":[null,null],"reignNote":"VII. yüzyıl başı. Hakan olduğu yazılmaz; Sâsânîlere karşı sefer açan Hazar kumandanı diye anılır.","summary":"Aras'a kadar Kuzey Azerbaycan'ı aldı. 629'da Tiflis zaptedildi. Başkent o sırada Belencer'di.","traits":[],"contribution":"Hazar akınını Güney Kafkasya'ya taşıdı.","harm":"","wives":[],"children":[],"wars":[{"name":"Tiflis","when":"629","foe":"Sâsânîler","result":"zafer","note":"TDV zaptı Hazar seferine bağlar; Çorpan'ın bizzat Tiflis'te olduğu ayrıca belirtilmez."}],"legends":[],"sources":[{"title":"TDV İslâm Ansiklopedisi, HAZARLAR","url":"https://islamansiklopedisi.org.tr/hazarlar"}]},{"id":"hazar-as-tarhan","name":"As-Tarhan","title":"tarhan","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"kayıtlarda yok","reign":[null,null],"reignNote":"764 seferinin kumandanı. Hakan değildir.","summary":"Hazar prensesinin doğumda ölmesi üzerine hakanın gönderdiği ordunun başında Tiflis'i aldı.","traits":[],"contribution":"","harm":"764'te Tiflis ele geçirildi.","wives":[],"children":[],"wars":[{"name":"Tiflis seferi","when":"764","foe":"Abbâsîler","result":"zafer","note":"Yezîd b. Esîd'in Hazar hatununun ölümünden sonra."}],"legends":[],"sources":[{"title":"TDV İslâm Ansiklopedisi, HAZARLAR","url":"https://islamansiklopedisi.org.tr/hazarlar"}]},{"id":"hazar-bulan","name":"Bulan","title":"hakan","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"kayıtlarda yok","reign":[null,null],"reignNote":"Yalnızca Hakan Yûsuf'un mektubunda, Yahudiliğe giriş onun zamanına bağlanır. Yıl yok.","summary":"Hasdai ben Şaprut'a cevap diye bilinen mektupta Hazarların Yahudiliğe Bulan zamanında girdiği yazılır. Olay bir rüyaya bağlanır. Mektup dışında adı doğrulanmaz.","traits":[],"contribution":"","harm":"","wives":[],"children":[],"wars":[],"legends":["Mektup, dini seçişi Bulan'ın rüyasına bağlar.","Bulu Han biçimi ve Böri Şad ile özdeşleştirme açılan TDV ve Britannica maddelerinde yoktur."],"sources":[{"title":"TDV İslâm Ansiklopedisi, HAZARLAR","url":"https://islamansiklopedisi.org.tr/hazarlar"}]},{"id":"hazar-obadiah","name":"Obadiah","title":"hakan","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"kayıtlarda yok","reign":[null,null],"reignNote":"Yine yalnızca Yûsuf mektubunda, Bulan'dan sonraki din düzenlemesi onun adına yazılır.","summary":"Mektuba göre sinagog ve okul açtırdı; Tevrat, Mişna ve Talmud öğretimi onun zamanında yayıldı. Bağımsız bir doğrulama yoktur.","traits":[],"contribution":"","harm":"","wives":[],"children":[],"wars":[],"legends":["Obadiah'ın ıslahatı mektubun anlatısıdır; yılı ve saltanatı ayrıca kayıtlı değildir."],"sources":[{"title":"TDV İslâm Ansiklopedisi, HAZARLAR","url":"https://islamansiklopedisi.org.tr/hazarlar"}]},{"id":"hazar-yusuf","name":"Yûsuf","title":"hakan","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"kayıtlarda yok","reign":[950,960],"reignNote":"Hasdai mektubu TDV'ye göre 950-960 arasında yazılmış sayılır. Bu aralık saltanatın tamamı değildir.","summary":"Endülüs veziri Hasdai ben Şaprut ile mektuplaştığı ileri sürülen X. yüzyıl hakanı. Mektup Hazar tarihini ve Bulan'ı anlatır. Cambridge belgesi de Yûsuf ile Hârun'un Ruslara karşı direndiğini söyler.","traits":[],"contribution":"Hazarların Yahudiliğe girişine dair başlıca yerli anlatı onun mektubuna dayanır.","harm":"","wives":[],"children":[],"wars":[{"name":"Sviatoslav seferi","when":"965-969","foe":"Kiev knezi Sviatoslav","result":"yenilgi","note":"965'te gücün kırılması Britannica ve TDV'de vardır. 965'teki hakanın Yûsuf olduğu kesin değildir. Semender 968'den sonra, Atil Vikipedi'ye göre 969'da yağmalandı."}],"legends":["Mektup Hazarları Togarmah oğlu Kozar'a bağlar. Bu bir soy efsanesidir."],"sources":[{"title":"TDV İslâm Ansiklopedisi, HAZARLAR","url":"https://islamansiklopedisi.org.tr/hazarlar"},{"title":"Britannica, Khazar","url":"https://www.britannica.com/topic/Khazar"}]},{"id":"hazar-harun","name":"Hârun","title":"hakan","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"kayıtlarda yok","reign":[null,null],"reignNote":"Yalnızca Cambridge belgesinde, Yûsuf ile birlikte Ruslara karşı anılır.","summary":"Adı bilinmeyen bir Hazar Yahudisinin mektubunda Rus direnişinin hükümdarlarından biri diye geçer. Ayrı bir saltanat yılı yoktur.","traits":[],"contribution":"","harm":"","wives":[],"children":[],"wars":[],"legends":[],"sources":[{"title":"TDV İslâm Ansiklopedisi, HAZARLAR","url":"https://islamansiklopedisi.org.tr/hazarlar"}]}]},{"id":"buyuk-bulgarya","name":"Büyük Bulgarya","short":"Kubrat'ın Karadeniz kuzeyinde kurduğu kısa ömürlü Bulgar birliği","aliases":["Magna Bulgaria","Büyük Bulgar Devleti","Patria Onoguria"],"region":"bati","start":630,"end":665,"startNote":"TDV bağımsızlığı 630'a, Britannica Avarlara isyanı 635'e koyar. Britannica saltanat başlangıcını yaklaşık 605, TDV Bulgar maddesi 584 diye de yazar.","endNote":"Kurucunun ölümü TDV İdil ve Türk maddelerinde 665, TDV Bulgar ve Britannica'da yaklaşık 642, TDV Bulgaristan'da 650'lerdedir. Dağılma Hazar baskısıyladır.","capital":"Sabit şehir adı kayıtlarda yok; güney sınır Kuban","religion":"Açılan sayfalarda resmî din adı yok","confidence":"tartismali","confidenceNote":"Birliğin varlığı Bizans kayıtlarına dayanır. Kurucunun adı Kurt, Kobrat, Kubrat, Kuvrat biçimlerinde gelir. Ölüm yılı üç ayrı TDV maddesinde uyuşmaz. Doulo sülalesinin Asya Hun T'u-ko hanedanına bağlanması TDV'de bir iddiadır, kanıtlanmış soy değildir. Bulgarların Türk mü, İranî unsurlu mu olduğu Britannica'da açık bırakılır.","summary":"Ogur ve Kutrigur-Utrigur Bulgarları, Avar ve Göktürk baskısı zayıflayınca Kubrat altında Kuban-Azak-Karadeniz kuzeyinde toplandı. TDV Bulgaristan batı sınırını Dinyeper, doğuyu İdil, güneyi Kuban diye çizer. Kurucu ölünce oğullar dağıldı; bir kol Hazarlara kaldı, biri Tuna'ya, biri Orta İdil'e gitti.","legacy":"Tuna Bulgar Devleti ile İdil Bulgarlarının ortak çıkış noktası sayılır. Kendisi bir kuşak sürdü.","essay":["Ogur ve Kutrigur-Utrigur Bulgarları, Avar ve Göktürk baskısı zayıflayınca Kubrat önderliğinde Kuban-Azak-Karadeniz kuzeyinde toplandı; sınırları batıda Dinyeper, doğuda İdil, güneyde Kuban'a kadar uzandı. Kurucunun ölümünden sonra oğullar dağıldı: bir kol Hazarlara bağlandı, biri Tuna'ya, biri Orta İdil'e gitti.","Varlığı Bizans kayıtlarına dayanır; kurucunun adı Kurt, Kobrat, Kubrat, Kuvrat biçimlerinde gelir ve ölüm yılı kaynaklar arasında uyuşmaz (642-665). Tuna Bulgar Devleti ile İdil Bulgarlarının ortak çıkış noktası sayılır; kendisi bir kuşak sürdü."],"sources":[{"title":"TDV İslâm Ansiklopedisi, TÜRK","url":"https://islamansiklopedisi.org.tr/turk"},{"title":"TDV İslâm Ansiklopedisi, İDİL BULGAR HANLIĞI","url":"https://islamansiklopedisi.org.tr/idil-bulgar-hanligi"},{"title":"TDV İslâm Ansiklopedisi, BULGAR","url":"https://islamansiklopedisi.org.tr/bulgar"},{"title":"TDV İslâm Ansiklopedisi, BULGARİSTAN","url":"https://islamansiklopedisi.org.tr/bulgaristan"},{"title":"Britannica, Bulgar","url":"https://www.britannica.com/topic/Bulgar"}],"rulers":[{"id":"buyuk-bulgarya-kubrat","name":"Kubrat","title":"han","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"TDV İdil ve Türk 665; TDV Bulgar ile Britannica yaklaşık 642; TDV Bulgaristan 650'ler. Tek yıl seçilmedi.","reign":[630,null],"reignNote":"Britannica yaklaşık 605-642 ve 635 isyanı; TDV Bulgar 584-642; TDV Türk bağımsızlık 630.","summary":"Kurt, Kobrat, Kobratos ve Kuvrat diye de yazılır. Avar hâkimiyetini kırıp Büyük Bulgarya'yı topladı. Herakleios döneminde Bizans'la ilişki kurdu. Ölümünden sonra birlik Hazar baskısı ve oğulların ayrılmasıyla parçalandı.","traits":[],"contribution":"Dağınık Bulgar boylarını kısa süreli tek birlik haline getirdi.","harm":"","wives":[],"children":[{"name":"Bat-Bayan","mother":"","note":"TDV: On Ogur ve Macarların başında Kafkasya'da kalarak Hazarlara tâbi oldu","certainty":"olasi"},{"name":"Asparuh","mother":"","note":"Tuna'ya giden oğul. TDV Bulgar onu küçük oğul diye anar","certainty":"kesin"},{"name":"Kotrag","mother":"","note":"Britannica kuzeye, İdil-Kama yöresine giden oğul diye yazar. TDV bu kolu adsız Otuz-Ogur kitlesi sayar","certainty":"olasi"}],"wars":[{"name":"Avarlara isyan","when":"635","foe":"Avarlar","result":"zafer","note":"Britannica. TDV bağımsızlığı 630 Göktürk fetretine bağlar, tek muharebe adı vermez."}],"legends":["Doulo soyunun Asya Hun T'u-ko hanedanına çıktığı TDV'de yazılır; bu bir hanedan iddiasıdır."],"sources":[{"title":"TDV İslâm Ansiklopedisi, TÜRK","url":"https://islamansiklopedisi.org.tr/turk"},{"title":"TDV İslâm Ansiklopedisi, BULGARİSTAN","url":"https://islamansiklopedisi.org.tr/bulgaristan"},{"title":"Britannica, Bulgar","url":"https://www.britannica.com/topic/Bulgar"}]}]},{"id":"tuna-bulgar","name":"Tuna Bulgar Devleti","short":"Asparuh'tan Boris'in vaftizine kadar Türkçe han dönemi","aliases":["Birinci Bulgar Devleti","Tuna Bulgar Hanlığı"],"region":"bati","start":681,"end":864,"startNote":"TDV Türk, Balkanlar'a geçişi 668 ve kuruluşu 679 diye de yazar. Bizans'ın antlaşmayla tanıması 681'dir.","endNote":"Boris'in vaftizi TDV İdil, Türk, Bulgar ve Britannica'da 864; TDV Bulgaristan 865 yazar. Devlet sürdü fakat han unvanı ve Türkçe karakter bu tarihten sonra kalktı. Simeon 893'te çar unvanını aldı.","capital":"Pliska","religion":"Eski Türk inancı; 864'te Ortodoks Hıristiyanlık resmî oldu","confidence":"kayit","confidenceNote":"Kuruluş ve 864/865 vaftizi kayıtlıdır. 718-803 arası hanların adları bu turda açılan sayfalarda dökülmediği için yazılmadı. Omurtag'ın başlangıcı 814 veya 816 diye ayrılır. Boris'in cülûsu TDV Bulgar'da 859, Bulgaristan ve Britannica'da 852'dir.","summary":"Kubrat'ın oğlu Asparuh, Hazar baskısı üzerine Tuna'yı geçip yedi Slav boyu ve Severilerle Bizans'a karşı tutundu. 681 antlaşması vergi ve tanıma getirdi. Krum ve Omurtag döneminde sınır ve imar genişledi. Boris'in vaftiziyle hanlık Slav-Hıristiyan bir çarlığa döndü; Türkçe unvan ve dil eridi.","legacy":"Bugünkü Bulgaristan'ın adı ve ilk devlet çekirdeği bu hanlıktandır. Yönetici Bulgarlar Slav çoğunluk içinde eridi. 864'ten sonrası bu kaydın dışındadır.","essay":["Kubrat'ın oğlu Asparuh, Hazar baskısı üzerine Tuna'yı geçip yedi Slav boyu ve Severilerle Bizans'a karşı tutundu; 681 antlaşması vergi ve karşılıklı tanımayı getirdi. Krum ve Omurtag döneminde sınırlar genişledi, imar ve merkezîleşme arttı.","Boris'in 864'teki vaftiziyle hanlık Slav-Hıristiyan bir çarlığa döndü; han unvanı ve Türkçe karakter geriledi, 893'te Simeon çar unvanını aldı. Bugünkü Bulgaristan'ın devlet çekirdeği bu hanlıktan gelir; yönetici Bulgarlar Slav çoğunluk içinde eridi."],"sources":[{"title":"TDV İslâm Ansiklopedisi, BULGAR","url":"https://islamansiklopedisi.org.tr/bulgar"},{"title":"TDV İslâm Ansiklopedisi, BULGARİSTAN","url":"https://islamansiklopedisi.org.tr/bulgaristan"},{"title":"TDV İslâm Ansiklopedisi, TÜRK","url":"https://islamansiklopedisi.org.tr/turk"},{"title":"Britannica, Bulgar","url":"https://www.britannica.com/topic/Bulgar"},{"title":"Britannica, Bulgaria","url":"https://www.britannica.com/place/Bulgaria/History"}],"rulers":[{"id":"tuna-bulgar-asparuh","name":"Asparuh","title":"han","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"kayıtlarda yok","reign":[681,null],"reignNote":"İsperih ve Esperih diye de yazılır. Tuna'yı geçiş TDV Türk'te 668. Tanınma 681.","summary":"Kubrat'ın oğlu. Dobruca ve Tuna güneyinde Slav boylarıyla birlikte Bizans'ı antlaşmaya zorladı. Başkent Pliska oldu. Ordu ve birliğin başı Bulgar hanıydı.","traits":[],"contribution":"Tuna Bulgar Devleti'ni Bizans'a tanıttı.","harm":"Trakya akınında kentler tahrip edildi.","wives":[],"children":[],"wars":[{"name":"Onglos ve Tuna savaşı","when":"681","foe":"Bizans imparatoru IV. Konstantinos","result":"zafer","note":"İstanbul kuşatması (674-678) sırasında açıldığı TDV Bulgar'da yazılır."},{"name":"681 antlaşması","when":"681","foe":"Bizans","result":"antlasma","note":"Yıllık vergi ve devletin tanınması."}],"legends":[],"sources":[{"title":"TDV İslâm Ansiklopedisi, BULGARİSTAN","url":"https://islamansiklopedisi.org.tr/bulgaristan"},{"title":"TDV İslâm Ansiklopedisi, İDİL BULGAR HANLIĞI","url":"https://islamansiklopedisi.org.tr/idil-bulgar-hanligi"}]},{"id":"tuna-bulgar-tervel","name":"Tervel","title":"han","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"kayıtlarda yok","reign":[701,718],"reignNote":"TDV Bulgaristan ve Britannica bu yılları verir. Asparuh'un oğlu olduğu yazılmaz.","summary":"II. Iustinianos'un tahta dönüşüne yardım etti. Karşılığında Zagore ve imparatordan sonraki bir unvan aldı. 717'de İstanbul'u kuşatan Arap kuvvetlerine Trakya'da saldırdı.","traits":[],"contribution":"717-718 kuşatmasında Bizans'ın yanında yer aldı.","harm":"","wives":[],"children":[],"wars":[{"name":"İstanbul kuşatması","when":"717-718","foe":"Emevî ordusu","result":"zafer","note":"Bulgarlar Bizans'ın yanında savaştı. Şehir düşmedi."}],"legends":[],"sources":[{"title":"TDV İslâm Ansiklopedisi, BULGARİSTAN","url":"https://islamansiklopedisi.org.tr/bulgaristan"},{"title":"Britannica, Bulgar","url":"https://www.britannica.com/topic/Bulgar"}]},{"id":"tuna-bulgar-krum","name":"Krum","title":"han","birth":null,"birthNote":"kayıtlarda yok","death":814,"deathNote":"TDV Türk: İstanbul kuşatması sırasında öldü.","reign":[803,814],"reignNote":"TDV Bulgar Kurum Han diye 803-814 yazar. 718-803 arası hanlar bu dosyada yok.","summary":"Tuna Bulgarlarının parlak dönemini açtı. Slav ve Bulgar nüfusu birleştirmeye çalıştı, kanun çıkardığı kaydedilir. Sofya'dan Üsküp'e ticaret yolları bu çağda Bulgar eline geçti.","traits":[],"contribution":"Devleti VIII. yüzyıl gerilemesinden çıkardı.","harm":"Bizans ordusunu imha etti; imparatorun kafatasından kadeh yaptırdığı Britannica'da yazılır.","wives":[],"children":[{"name":"Omurtag","mother":"","note":"TDV Türk yerine geçen oğul diye yazar","certainty":"olasi"}],"wars":[{"name":"Nikeforos seferi","when":"803-814 arası","foe":"Bizans imparatoru I. Nikeforos","result":"zafer","note":"İmparatorluk ordusu imha edildi. Yıl açılan sayfada yok. Kafatası kadehi Britannica'da vardır."},{"name":"İstanbul kuşatması","when":"814","foe":"Bizans","result":"yenilgi","note":"Şehir alınamadı. Krum kuşatma sırasında öldü."}],"legends":["Nikeforos'un kafatasının gümüş kaplanıp kadeh yapılması Britannica'da kayıtlı bir anlatıdır."],"sources":[{"title":"TDV İslâm Ansiklopedisi, BULGAR","url":"https://islamansiklopedisi.org.tr/bulgar"},{"title":"TDV İslâm Ansiklopedisi, TÜRK","url":"https://islamansiklopedisi.org.tr/turk"},{"title":"Britannica, Bulgaria","url":"https://www.britannica.com/place/Bulgaria/History"}]},{"id":"tuna-bulgar-omurtag","name":"Omurtag","title":"han","birth":null,"birthNote":"kayıtlarda yok","death":831,"deathNote":"Saltanat sonu 831 diye yazılır; ölüm biçimi yok.","reign":[814,831],"reignNote":"TDV Türk ve Bulgar 814-831. TDV Bulgaristan 816-831.","summary":"Bizans'la otuz yıllık barış yaptı. Franklarla uğraştı, Tuna-Sava-Drava havzasını ve Maroş tuzlalarını aldığı TDV'de yazılır. Pliska, Preslav ve Madara'daki yapı ve Krum kayalığı bu çağa bağlanır.","traits":[],"contribution":"Güneyde sükûn, tuz ve imar getirdi.","harm":"","wives":[],"children":[],"wars":[{"name":"Bizans'la otuz yıllık barış","when":"814'ten sonra","foe":"Bizans","result":"antlasma","note":"Bulgaristan maddesi bunu Omurtag dönemine koyar."},{"name":"Frank mücadelesi","when":"814-831","foe":"Franklar","result":"zafer","note":"TDV tek muharebe adı vermez; Tuna-Sava-Drava'nın alındığını yazar."}],"legends":[],"sources":[{"title":"TDV İslâm Ansiklopedisi, TÜRK","url":"https://islamansiklopedisi.org.tr/turk"},{"title":"TDV İslâm Ansiklopedisi, BULGARİSTAN","url":"https://islamansiklopedisi.org.tr/bulgaristan"}]},{"id":"tuna-bulgar-malamir","name":"Malamir","title":"han","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"kayıtlarda yok","reign":[831,836],"reignNote":"TDV Bulgar ve Bulgaristan aynı yılları verir.","summary":"Filibe'yi aldı. Bu dönemde Hıristiyanlık Bizans etkisiyle Bulgarlar arasında yayılmaya başladı; resmî din henüz değişmedi.","traits":[],"contribution":"","harm":"","wives":[],"children":[],"wars":[{"name":"Filibe","when":"831-836","foe":"Bizans","result":"zafer","note":"TDV Bulgaristan ele geçirmeyi yazar, muharebe adı vermez."}],"legends":[],"sources":[{"title":"TDV İslâm Ansiklopedisi, BULGAR","url":"https://islamansiklopedisi.org.tr/bulgar"},{"title":"TDV İslâm Ansiklopedisi, BULGARİSTAN","url":"https://islamansiklopedisi.org.tr/bulgaristan"}]},{"id":"tuna-bulgar-presiyan","name":"Presiyan","title":"han","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"kayıtlarda yok","reign":[836,852],"reignNote":"TDV Bulgar Persiyan 836-852, Türk maddesi 837-852, Bulgaristan Presiyan 836-852. Britannica Pressian 836-852.","summary":"Makedonya'da Slav boylarının oturduğu yerleri ve Rodopları aldığı kaydedilir. Hıristiyanlığın yayılması sürdü.","traits":[],"contribution":"Makedonya ve Rodop yönünde sınır genişledi.","harm":"","wives":[],"children":[],"wars":[{"name":"Makedonya ve Rodop seferleri","when":"836-852","foe":"Bizans","result":"zafer","note":"Tek muharebe adı yok."}],"legends":[],"sources":[{"title":"TDV İslâm Ansiklopedisi, BULGARİSTAN","url":"https://islamansiklopedisi.org.tr/bulgaristan"},{"title":"Britannica, Bulgar","url":"https://www.britannica.com/topic/Bulgar"}]},{"id":"tuna-bulgar-boris","name":"Boris","title":"han","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"Açılan sayfalarda ölüm yılı yok. Saltanat 889'da biter.","reign":[852,889],"reignNote":"TDV Bulgaristan ve Britannica 852-889. TDV Bulgar 859-890. Vaftiz 864; Bulgaristan maddesi 865. Vaftiz adı Mikhail. Bu dosya Türkçe han dönemini vaftizde keser.","summary":"Hıristiyanlığı resmen kabul etti ve halkı vaftiz ettirdi. TDV Türk, o zamana kadar tek tanrı inancı taşıyan Bulgarların bu tarihte hıristiyanlaştığını ve devletin Slav-Bizans kültürüne girdiğini yazar. Halefi Simeon han yerine çar unvanını kullandı.","traits":[],"contribution":"Vaftiz, Slav ve Bulgar nüfusunu tek kilise altında birleştirdi.","harm":"Türkçe han unvanı ve yönetici dil bu seçimle silindi.","wives":[],"children":[{"name":"Simeon","mother":"","note":"TDV Türk halef diye 893-917, Bulgaristan 893-927 yazar. Çar unvanı vaftizden sonradır","certainty":"olasi"}],"wars":[],"legends":[],"sources":[{"title":"TDV İslâm Ansiklopedisi, BULGARİSTAN","url":"https://islamansiklopedisi.org.tr/bulgaristan"},{"title":"TDV İslâm Ansiklopedisi, TÜRK","url":"https://islamansiklopedisi.org.tr/turk"},{"title":"TDV İslâm Ansiklopedisi, BULGAR","url":"https://islamansiklopedisi.org.tr/bulgar"}]}]},{"id":"itil-bulgar","name":"İtil Bulgar Devleti","short":"Orta İdil'de İslâm'ı resmen kabul eden Bulgar hanlığı, 1236'ya kadar","aliases":["İdil Bulgar Hanlığı","Volga Bulgarları"],"region":"kuzey","start":922,"end":1236,"startNote":"Kuzeye çekiliş VII. yüzyıl sonu ile VIII. yüzyıl başı. Hazar tâbiiyeti 965'e kadar sürdü. Resmî İslâm ve elçilik 922. Başlangıç yılı olarak bu tarih alındı.","endNote":"TDV Batu'nun yakıp yıkmasını 1236'ya, Britannica Altın Orda'ya bağlanmayı 1237'ye koyar. Yarı bağımlı hayat Altın Orda'da sürdü; bu kayıt 1236'da biter.","capital":"Bulgar","religion":"Önce eski Türk inancı; 922'den sonra İslâm","confidence":"kayit","confidenceNote":"922 elçiliği İbn Fadlân üzerinden kayıtlıdır. Han adı Almış'tır. TDV Bulgar maddesindeki 'Yaltavar oğlu' ifadesi unvanı baba adı gibi okur; İdil maddesi babayı Şilkey, unvanı yeltever/ilteber diye ayırır. Kotrag adı yalnızca Britannica'dadır. Sikkelerdeki diğer hanların 1236'dan önce mi sonra mı olduğu ayırt edilmez.","summary":"Büyük Bulgarya dağılınca Otuz-Ogur kolu Orta İdil ve Kama'ya çekildi. Fin-Ogur komşularını bağlayıp kürk, bal ve İdil ticaretine oturdu. Almış Han 922'de Abbâsî elçilerini kabul edip İslâm'ı resmen aldı. 965'te Hazar darbesinden sonra tam bağımsız kaldı. 1223'te bir Moğol tümenini yendiler; 1236'da Batu ülkeyi yaktı.","legacy":"İslâm'ı resmî din yapan ilk Türk devleti diye anılır. Bulgar gönü ve taş yapı izleri kaldı. Dil yadigârları Çuvaşçanın öncülü sayılır. Moğol sonrası Kıpçakça ağır bastı.","essay":["Büyük Bulgarya dağılınca Otuz-Ogur kolu Orta İdil ve Kama'ya çekildi; Fin-Ogur komşularını çevresine katarak kürk, bal ve İdil ticaretine yerleşti. Almış Han 922'de Abbâsî elçilerini kabul edip İslâm'ı resmen aldı; bu yönüyle İslâm'ı resmî din yapan ilk Türk devleti sayılır.","965'teki Hazar darbesinden sonra tam bağımsız kaldılar; 1223'te bir Moğol tümenini yendilerse de 1236'da Batu ülkeyi yaktı. Bulgar gönü ve taş yapı izleri kaldı; dil yadigârları Çuvaşçanın öncülü sayılır, Moğol sonrası Kıpçakça ağır bastı."],"sources":[{"title":"TDV İslâm Ansiklopedisi, İDİL BULGAR HANLIĞI","url":"https://islamansiklopedisi.org.tr/idil-bulgar-hanligi"},{"title":"TDV İslâm Ansiklopedisi, BULGAR","url":"https://islamansiklopedisi.org.tr/bulgar"},{"title":"Britannica, Bulgar","url":"https://www.britannica.com/topic/Bulgar"}],"rulers":[{"id":"itil-bulgar-almis","name":"Almış","title":"ilteber","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"kayıtlarda yok","reign":[922,null],"reignNote":"Şilkey oğlu. Unvanı yeltever/ilteber/yaltavar. Bitiş yılı yok. Elçi 12 Muharrem 310 (12 Mayıs 922) karargâha vardı. TDV Bulgar elçinin yola çıkışını 920 diye de yazar.","summary":"Abbâsî halifesi Muktedir-Billâh'tan din adamı istedi. Sevsen er-Ressî heyetinde kâtip İbn Fadlân vardı. Han ve ileri gelenler İslâm'ı kabul etti. Halife ve han adına sikke basıldı, cami ve kadılık kuruldu.","traits":[],"contribution":"İdil Bulgar ülkesini resmen müslüman bir hanlık haline getirdi.","harm":"","wives":[],"children":[],"wars":[],"legends":[],"sources":[{"title":"TDV İslâm Ansiklopedisi, İDİL BULGAR HANLIĞI","url":"https://islamansiklopedisi.org.tr/idil-bulgar-hanligi"},{"title":"TDV İslâm Ansiklopedisi, BULGAR","url":"https://islamansiklopedisi.org.tr/bulgar"},{"title":"TDV İslâm Ansiklopedisi, OĞUZLAR","url":"https://islamansiklopedisi.org.tr/oguzlar"}],"familyNotes":["İbn Fadlân anlatısındaki Etrek-Almış yakınlığı bir kızın Almış’ın çocuğu olduğunu tek başına kanıtlamaz; kız kaydı çıkarıldı."]},{"id":"itil-bulgar-han-adi-yok","name":"kayıtlarda adı geçmiyor","title":"han","birth":null,"birthNote":"kayıtlarda adı geçmiyor","death":null,"deathNote":"kayıtlarda adı geçmiyor","reign":[null,1236],"reignNote":"964, 985, 1223 ve 1236 olaylarının han adı TDV'de yoktur. Sikke adları (Şülkî, Ahmed, Tâlib, Mü'min, Haydar, Muhammed, Saîd b. Haydar, Baraj, İbrâhim, Selim, İlham, Abdullah, Hasan, Mahmud, Altınbek, Âlimbek) yıllara bağlanamadığı için ayrı hükümdar yazılmadı.","summary":"Almış'tan sonraki müslüman hanların sırası sikke adlarıyla sınırlıdır. 965'te Hazar zayıflayınca tam bağımsızlık geldi. Moğol öncesi hanın adı verilmez.","traits":[],"contribution":"","harm":"","wives":[],"children":[],"wars":[{"name":"Kiev akınları","when":"964 ve 985","foe":"Kiev Rus knezliği","result":"zafer","note":"TDV akınların etkisizleştirildiğini yazar."},{"name":"Ticaret antlaşması","when":"1006","foe":"Kiev","result":"antlasma","note":""},{"name":"1223 Moğol çarpışması","when":"1223","foe":"Moğol öncü ordusu","result":"zafer","note":"Kalka'dan dönen Moğol kuvveti İdil Bulgarlarınca imha edildi."},{"name":"Batu seferi","when":"1236","foe":"Batu Han","result":"yenilgi","note":"Ülke ve Bulgar şehri yakıldı. Britannica bağlanmayı 1237 diye yazar."}],"legends":[],"sources":[{"title":"TDV İslâm Ansiklopedisi, İDİL BULGAR HANLIĞI","url":"https://islamansiklopedisi.org.tr/idil-bulgar-hanligi"}]}]},{"id":"oguz-yabgu","name":"Oğuz Yabgu Devleti","short":"Aşağı Seyhun'da yabgu unvanlı Oğuz birliği","aliases":["Oğuz Yabguluğu","Yenikent Oğuzları"],"region":"turkistan","start":775,"end":1003,"startNote":"Aşağı Seyhun'a geliş TDV'de Halife Mehdî dönemi (775-785) tahminidir. Bağımsız ve güçlü yabguluk X. yüzyılın ilk yarısında kaydedilir. Kuruluş yılı yoktur.","endNote":"TDV, Sâmânî İsmâil b. Nûh'un 1003'te başvurduğu Oğuzların artık Selçuklu kolu olduğunu ve yabgu devletinin bu tarihten önce bittiğini yazar. Kesin yıkılış yılı yok. Kıpçakların yıktığı ihtimali zayıf diye ayrılır.","capital":"Yenikent","religion":"Geleneksel Türk dini; X. yüzyılda İslâmiyet boy boy yayıldı","confidence":"kayit","confidenceNote":"X. yüzyılda yabgu, kül erkin ve subaşı düzeni İbn Fadlân ve coğrafyacılarda vardır. Câmiü't-tevârîh'teki yabgu adları başka kaynakta geçmez; yazılmadı. Selçuk'un Yenikent'ten ayrılışı 961, 925-940, 955 veya 985-986 diye verilir.","summary":"Batı Göktürk geleneğinden gelen Oğuzlar Aşağı Seyhun, Aral ve Mangışlak arasında göçerdi. Kışlığı Yenikent olan yabgunun vekili kül erkin, ordu başı subaşıydı. Peçenekleri Yayık ötesine sürdüler. İç çekişme ve Selçuk'un Cend'e ayrılmasıyla birlik X. yüzyıl sonunda dağıldı.","legacy":"Selçuklu kolu bu ayrılmadan çıktı. Oğuz adı Türkiye, Azerbaycan ve Türkmenistan Türklerinin atasoyu anlatısında kaldı. Yabgu unvanı Selçuk'un oğullarında bir süre sürdü.","essay":["Batı Göktürk geleneğinden gelen Oğuzlar Aşağı Seyhun, Aral ve Mangışlak arasında göçerdi; kışlığı Yenikent olan yabgunun vekili kül erkin, ordu başı subaşıydı. Peçenekleri Yayık ötesine sürdüler.","İç çekişme ve Selçuk'un Cend'e ayrılmasıyla birlik X. yüzyılın sonunda dağıldı; Selçuklu kolu bu ayrılmadan doğdu. Oğuz adı Türkiye, Azerbaycan ve Türkmenistan Türklerinin atasoyu anlatısında yaşadı; yabgu unvanı Selçuk'un oğullarında bir süre sürdü."],"sources":[{"title":"TDV İslâm Ansiklopedisi, OĞUZLAR","url":"https://islamansiklopedisi.org.tr/oguzlar"},{"title":"TDV İslâm Ansiklopedisi, SELÇUK BEY","url":"https://islamansiklopedisi.org.tr/selcuk-bey"},{"title":"TDV İslâm Ansiklopedisi, YABGU","url":"https://islamansiklopedisi.org.tr/yabgu"}],"rulers":[{"id":"oguz-yabgu-adi-yok","name":"kayıtlarda adı geçmiyor","title":"yabgu","birth":null,"birthNote":"kayıtlarda adı geçmiyor","death":null,"deathNote":"Bir yabgunun Karluk savaşında öldüğü TDV'de vardır; adı ve yılı yok. Olay IX. yüzyıl veya daha önce diye tahmin edilir.","reign":[null,null],"reignNote":"Destandaki yabgu listesi başka kaynakta doğrulanmaz.","summary":"X. yüzyıl yabgusunun özel adı bağımsız kaynakta yoktur. Kışın Yenikent'te oturur, işleri meclisle görürdü. Dukak'la kılıçlı kavga anlatısı Selçuklu kaynaklarındadır.","traits":[],"contribution":"","harm":"","wives":[],"children":[],"wars":[{"name":"Karluk savaşı","when":"IX. yüzyıl veya daha önce","foe":"Karluklar","result":"yenilgi","note":"Yabgu öldü. Tek savaşın yılı yoktur."},{"name":"Peçeneklerin sürülmesi","when":"898-902","foe":"Peçenekler","result":"zafer","note":"Hazarlarla anlaşıp Peçenekleri İdil batısına sürdüler. Yıl aralığı TDV Oğuzlar'da 898-902, Peçenek maddesinde hücum 889'dur."}],"legends":["Câmiü't-tevârîh'te Kayı, Yazır, Avşar ve Eymir boyundan çıktığı söylenen yabgu adları başka kaynakta yoktur."],"sources":[{"title":"TDV İslâm Ansiklopedisi, OĞUZLAR","url":"https://islamansiklopedisi.org.tr/oguzlar"}]},{"id":"oguz-dukak","name":"Dukak","title":"subaşı","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"Selçuk 17-18 yaşındayken öldü. Yıl yok.","reign":[null,null],"reignNote":"Yabgu değil. Temür Yalığ (demir yaylı) lakabıyla anılan subaşı veya boy başbuğu.","summary":"Selçuk'un babası. Oğuz yabgusunun danıştığı nüfuzlu bir komutandı. Bir seferde yabguyla çatıştığı, yaraladığı ve sonra barıştırıldığı Selçuklu kaynaklarında yazılır. Hazar hakanına tâbi olduğu iddiasına TDV şüpheyle bakar.","traits":[],"contribution":"","harm":"","wives":[],"children":[{"name":"Selçuk","mother":"","note":"Bazı geç kaynaklar babayı Lokman diye yazar; TDV bunu Dukak'ın bozulması sayar","certainty":"olasi"}],"wars":[],"legends":["Yabguyu gürzle attan düşürdüğü sahne Ahbâr ve İbnü'l-Esîr çizgisindedir."],"sources":[{"title":"TDV İslâm Ansiklopedisi, SELÇUK BEY","url":"https://islamansiklopedisi.org.tr/selcuk-bey"}]},{"id":"oguz-etrek","name":"Etrek","title":"subaşı","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"kayıtlarda yok","reign":[921,null],"reignNote":"921'de elçilik heyetini karşılayan subaşı. Yabgu değildir. İl Doğan oğlu diye anılır.","summary":"Abbâsî elçilerine karşı ne yapılacağını tarhan ve yinaları toplayıp sordu. İdil Bulgar hanı Almış'ın damadıydı.","traits":[],"contribution":"Oğuz meclis usulü onun 921 kaydında görülür.","harm":"","wives":[],"children":[],"wars":[],"legends":[],"sources":[{"title":"TDV İslâm Ansiklopedisi, OĞUZLAR","url":"https://islamansiklopedisi.org.tr/oguzlar"}],"familyNotes":["Etrek ile Almış arasında akrabalık ilişkisi anılır; Almış’ın kızıyla evlendiği teyit edilemedi."]},{"id":"oguz-selcuk","name":"Selçuk","title":"subaşı","birth":null,"birthNote":"Yaklaşık 287/900 tahmini. Kesin yıl yok.","death":1007,"deathNote":"Yaklaşık 397/1007, Cend'de. 100 veya 107 yaşında dendiği için 1009-1010 da ileri sürülür.","reign":[961,1007],"reignNote":"Yabgu değil. Yenikent'ten ayrılış muhtemel 350/961; 925-940, 955 ve 985-986 da verilir. TDV Oğuzlar Meliknâme'ye göre 375/985-86.","summary":"Dukak ölünce yabgu onu subaşı yaptı. Hatunun kıskançlığı, otlak darlığı ve Kıpçak sıkıştırması anlatılarıyla Yenikent'ten Cend'e gitti. Orada İslâm'ı seçip yabgu devletiyle bağını kesti. Oğullarından İsrail, Arslan Yabgu unvanını aldı.","traits":[],"contribution":"Cend'de müslüman olup Selçuklu kolunu yabgu birliğinden ayırdı.","harm":"","wives":[{"name":"Adı bilinmeyen Türkmen hükümdarı kızı","note":"TDV, Türkmen hükümdarlarından birinin kızıyla evli olduğunu Köymen'e dayanarak yazar","certainty":"olasi"}],"children":[{"name":"Mîkâil","mother":"","note":"Muhtemelen bir seferde şehit düştü; yıl yok","certainty":"olasi"},{"name":"İsrâil","mother":"","note":"Arslan Yabgu. Üç oğullu listenin parçası","certainty":"olasi"},{"name":"Mûsâ","mother":"","note":"Üç oğullu listenin parçası","certainty":"olasi"},{"name":"Yûnus","mother":"","note":"Yalnızca bazı kaynaklardaki dört ve beş oğullu listede","certainty":"rivayet"},{"name":"Yûsuf","mother":"","note":"Yinal diye de anılır; yalnızca beş oğullu listede","certainty":"rivayet"}],"wars":[],"legends":["Soyun Efrâsiyâb'a bağlanması İbn Hassûl ve Nizâmülmülk'te vardır; TDV bunu efsane diye ayırır.","Hâce Kereküçü oğlu Tokşurmuş adlı ata başka kaynakta doğrulanmaz."],"sources":[{"title":"TDV İslâm Ansiklopedisi, SELÇUK BEY","url":"https://islamansiklopedisi.org.tr/selcuk-bey"},{"title":"TDV İslâm Ansiklopedisi, OĞUZLAR","url":"https://islamansiklopedisi.org.tr/oguzlar"}]}]},{"id":"pecenek","name":"Peçenek birliği","short":"Merkezi krallığı olmayan, boy beylerinden oluşan bozkır birliği","aliases":["Becenâk","Patzinak"],"region":"bati","start":895,"end":1091,"startNote":"Hazar-Oğuz darbesi 889 (276 hicrî). Don'dan Tuna'ya hâkimiyet 895. Britannica Karadeniz kuzeyini VIII-XII. yüzyıl diye geniş tutar.","endNote":"TDV siyasî gücün 29 Nisan 1091'de bittiğini, son akının 1197'de yapıldığını yazar. Britannica 1122'deki ikinci Bizans zaferinin gücü fiilen yok ettiğini söyler.","capital":"","religion":"Kamlık; Hıristiyan misyonu tutmadı, İslâm bazı gruplarda yayıldı","confidence":"kayit","confidenceNote":"Boy düzeni Konstantinos Porfirogennetos'ta kayıtlıdır. Merkezî krallık yoktur. Kangar adının Kül Tigin'deki Keñeres ile birleştirilmesi TDV'de şüpheli görülür.","summary":"Önce Seyhun ve Aral, sonra Yayık-İdil arasında yaşayan Peçenekler 889-895'te batıya itildi. Macarları Pannonia'ya sürdüler ve Don-Tuna bozkırını tuttular. Sekiz boy ve kırk obaydılar. Hükümdarları yoktu; boy beyleri gerektiğinde toplanırdı. 1091'de Bizans-Kıpçak hattında ağır yenilgiyle siyasî birlikleri kırıldı.","legacy":"Macarların bugünkü yurda inmesinin başlıca sebebi oldular. Dağınık gruplar Macaristan, Bizans hizmeti ve Kıpçaklar içinde eridi. Oğuzlar arasında kalan kol Oğuz Peçenek boyunu oluşturdu.","essay":["Önce Seyhun-Aral, sonra Yayık-İdil arasında yaşayan Peçenekler 889-895 arasında batıya itildi; Macarları Pannonia'ya sürerek Don-Tuna bozkırını tuttular. Sekiz boy ve kırk oba hâlinde yaşadılar; merkezî hükümdarları yoktu, boy beyleri gerektiğinde toplanırdı.","1091'de Bizans-Kıpçak hattında aldıkları ağır yenilgiyle siyasî birlikleri kırıldı; dağınık gruplar Macaristan'da, Bizans hizmetinde ve Kıpçaklar içinde eridi. Macarların bugünkü yurda inmesinin başlıca sebebi oldular; Oğuzlar arasında kalan kol Oğuz Peçenek boyunu oluşturdu."],"sources":[{"title":"TDV İslâm Ansiklopedisi, PEÇENEKLER","url":"https://islamansiklopedisi.org.tr/pecenekler"},{"title":"Britannica, Pechenegs","url":"https://www.britannica.com/topic/Pechenegs"}],"rulers":[{"id":"pecenek-kure","name":"Küre","title":"boy beyi","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"kayıtlarda yok","reign":[972,null],"reignNote":"Kral değil. 972'de Sviatoslav'ı yenen başbuğ.","summary":"Bizans'ın müttefiki olarak Kiev knezi Sviatoslav'ı savaşta öldürdü. Bütün Peçeneklerin hükümdarı diye anılmaz.","traits":[],"contribution":"","harm":"","wives":[],"children":[],"wars":[{"name":"Sviatoslav çarpışması","when":"972","foe":"Kiev knezi Sviatoslav","result":"zafer","note":"Britannica prensin adını Sriatoslav diye yazar. Aynı kişi."}],"legends":[],"sources":[{"title":"TDV İslâm Ansiklopedisi, PEÇENEKLER","url":"https://islamansiklopedisi.org.tr/pecenekler"},{"title":"Britannica, Pechenegs","url":"https://www.britannica.com/topic/Pechenegs"}]},{"id":"pecenek-turak","name":"Turak","title":"boy beyi","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"kayıtlarda yok","reign":[1048,null],"reignNote":"Durak diye de yazılır. 1048'de on üç oymağın başbuğu. Kral değil.","summary":"Tuna kuzeyindeki ana kolun başıydı. Bizans'a sığınan Kegen'e yenildi, 140 beyle birlikte esir düştü, sonra Tuna boyuna döndü. 1049'da Bizans ordusunu yenip Edirne'ye vardı.","traits":[],"contribution":"","harm":"1048 akını Bulgaristan'ı yakıp yıktı.","wives":[],"children":[],"wars":[{"name":"Kegen'e karşı","when":"1048","foe":"Kegen ve Bizans","result":"yenilgi","note":"Esir düştü, sonra döndü."},{"name":"Edirne'ye kadar sefer","when":"1049","foe":"Bizans","result":"zafer","note":""}],"legends":[],"sources":[{"title":"TDV İslâm Ansiklopedisi, PEÇENEKLER","url":"https://islamansiklopedisi.org.tr/pecenekler"}]},{"id":"pecenek-kegen","name":"Kegen","title":"boy beyi","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"kayıtlarda yok","reign":[1048,null],"reignNote":"İki oymağın başbuğu. Bizans sınırına yerleştirildi.","summary":"Uzlara karşı ün kazandı. Bizans'a sığınıp Tuna ve Silistre yakınında toprak aldı. Bizans yardımıyla Turak'ı yendi.","traits":[],"contribution":"","harm":"","wives":[],"children":[],"wars":[{"name":"Turak'a karşı","when":"1048","foe":"Turak","result":"zafer","note":"Bizans desteğiyle."}],"legends":[],"sources":[{"title":"TDV İslâm Ansiklopedisi, PEÇENEKLER","url":"https://islamansiklopedisi.org.tr/pecenekler"}]}]},{"id":"kipcak-kuman","name":"Kıpçak-Kuman birliği","short":"Deşt-i Kıpçak'ta tek devleti olmayan boylar birliği","aliases":["Kumanlar","Polovets","Deşt-i Kıpçak"],"region":"bati","start":1054,"end":1241,"startNote":"Kıpçak adı VIII. yüzyıl Şine-Usu yazıtında geçer. Doğu Avrupa bozkırında Rus yıllıklarına ilk giriş 1054 Polovtsı diye. Bölge 1080'lerde Balkaş'tan Tuna ağzına yayıldı.","endNote":"Britannica Kumanların Macaristan'a sığınmasını 1237-1239'a, TDV Köten'in bozulmasını 1239'a, Altın Orda ile siyasî rolün bitmesini 1241'e koyar. Köten 1240-41 kışında Macaristan'da öldürüldü.","capital":"","religion":"Başta şamanlık; bir kısmı Ortodoks oldu, Kırım ve İdil'de İslâm yayıldı","confidence":"kayit","confidenceNote":"Tek merkezî devlet kuramadıkları TDV'de açıktır. Beş bölgenin (Orta Asya, İtil-Yayık, Don-Donets, Aşağı Dinyeper, Tuna) kendi başbuğları vardı. Kuman batıdaki addır; doğuda Kıpçak denir. Bölge hem Karadeniz kuzeyi hem İdil boyunu kapsar; bu kayıtta bölge bati tutuldu.","summary":"Kimeklerin bir kolu olan Kıpçaklar XI. yüzyıl ortasında Uzların ardından Güney Rusya bozkırına girdi. İslâm kaynakları bu alana Deşt-i Kıpçak dedi. Boylar ortak bir kral seçmedi. Rus knezleriyle hem savaştılar hem kız alıp verdiler. 1223 Kalka ve 1238-1239 Moğol seferleri birliği dağıttı.","legacy":"Altın Orda halkının dil tabanı oldular. Macaristan'da Kuman adıyla, Mısır'da Memlük sultanları arasında sürdüler. Codex Cumanicus dillerinden kalan başlıca derlemedir.","essay":["Kimeklerin bir kolu olan Kıpçaklar XI. yüzyıl ortasında Uzların ardından Güney Rusya bozkırına girdi; İslâm kaynakları bu alana Deşt-i Kıpçak dedi. Boylar ortak bir kral seçmedi; Rus knezleriyle hem savaştılar hem kız alıp verdiler.","1223 Kalka ve 1238-1239 Moğol seferleri birliği dağıttı. Kıpçaklar Altın Orda halkının dil tabanı oldu; Macaristan'da Kuman, Mısır'da Memlük sultanları arasında varlıklarını sürdürdüler. Codex Cumanicus, dillerinden kalan başlıca derlemedir."],"sources":[{"title":"TDV İslâm Ansiklopedisi, KIPÇAKLAR","url":"https://islamansiklopedisi.org.tr/kipcaklar"},{"title":"Britannica, Cuman","url":"https://www.britannica.com/topic/Cuman"}],"rulers":[{"id":"kipcak-atrak","name":"Atrak","title":"başbuğ","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"kayıtlarda yok","reign":[1118,1125],"reignNote":"Bütün Kıpçakların hükümdarı değil. Don-Kuban kolunun başbuğu. 1125'te Gürcistan'dan döndü.","summary":"Kızı Gürcü kralı IV. David ile evlendi. Eski sayımlarda bu kral II. David diye de geçer. 1118'de Gürcistan'a giden Kıpçaklardan 40.000 atlılık bir kuvvet kurulduğu TDV'de yazılır. Kendisi 1125'te yurduna döndü; gidenlerin çoğu kaldı.","traits":[],"contribution":"Gürcü ordusuna Kıpçak atlısı kattı.","harm":"","wives":[],"children":[{"name":"Gurandukht","mother":"","note":"Gürcü Kralı IV. David ile evlenen Atrak’ın kızı. Gürcüce adı Gurandukht; özgün Kıpçakça adı bilinmiyor.","certainty":"kesin"}],"wars":[{"name":"Selçuklu akınlarına karşı Gürcü seferleri","when":"1118-1125","foe":"Gürcistan’a yönelik Selçuklu akınları","result":"belirsiz","note":"TDV Gürcülerin bu atlılarla akınlara karşı koyduğunu yazar; tek meydan sonucu vermez."}],"legends":[],"sources":[{"title":"TDV İslâm Ansiklopedisi, KIPÇAKLAR","url":"https://islamansiklopedisi.org.tr/kipcaklar"},{"title":"Tinikashvili ve Kazaryan, Crusaders and Georgia: A Critical Approach to Georgian Historiography (Kadmos)","url":"https://kadmos.iliauni.edu.ge/index.php/kadmos/article/view/191"}]},{"id":"kipcak-barc","name":"Barc","title":"bey","birth":null,"birthNote":"kayıtlarda yok","death":null,"deathNote":"kayıtlarda yok","reign":[1227,null],"reignNote":"Britannica onu Kuman prensi diye anar. Merkezî kağan değildir.","summary":"1227'de 15.000 kişilik bir grupla vaftiz oldu. 1228'de Kuman piskoposluğu kuruldu. Bütün Deşt'in hükümdarı değildir.","traits":[],"contribution":"","harm":"","wives":[],"children":[],"wars":[],"legends":[],"sources":[{"title":"Britannica, Cuman","url":"https://www.britannica.com/topic/Cuman"}]},{"id":"kipcak-koten","name":"Köten","title":"başbuğ","birth":null,"birthNote":"kayıtlarda yok","death":1241,"deathNote":"Britannica, Macaristan'ın 1240-41 Moğol akınından hemen önce öldürüldüğünü yazar. Tek gün yok.","reign":[null,1241],"reignNote":"Kuthen diye de yazılır. Don-Donets kolunun başbuğu. Başlangıç yılı yok. 1239’da Macaristan’a sığındı. Bütün Kıpçakların kralı değil.","summary":"Moğol karşısında Don ve Donets'te dağıldı, 1239'da Macaristan'a sığındı. Rus direnişini örgütleme girişimi sonuçsuz kaldı. Macaristan'da tehlikeli yabancı sayılıp öldürüldü.","traits":[],"contribution":"","harm":"","wives":[],"children":[],"wars":[{"name":"Don-Donets bozgunu","when":"1239","foe":"Batu Han'ın ordusu","result":"yenilgi","note":"Kaçabilenler Macaristan'a gitti."}],"legends":[],"sources":[{"title":"TDV İslâm Ansiklopedisi, KIPÇAKLAR","url":"https://islamansiklopedisi.org.tr/kipcaklar"},{"title":"Britannica, Cuman","url":"https://www.britannica.com/topic/Cuman"}]}]}]`);export{e as default};